// Prints the libvpl struct layouts as Rust constants, for src/layout.rs. The FFI's
// size and offset asserts (src/ffi.rs tests) hold against these, so a transcription
// slip or a header bump that moves a field fails the build's tests, never the driver.
// `cargo xtask layout vpl` compiles and runs it in the devshell. ONEVPL_EXPERIMENTAL is
// defined, the surface sharing structs (mfxSurfaceVAAPI, mfxMemoryInterface) and the
// Export slot of mfxFrameSurfaceInterface are behind it in the 2.16 headers.
#define ONEVPL_EXPERIMENTAL 1
#include <stdio.h>
#include <stddef.h>
#include <vpl/mfx.h>

#define SIZE(T) printf("pub const %s_SIZE: usize = %zu;\n", #T, sizeof(T))
#define OFF(T, f, name) printf("pub const %s_%s: usize = %zu;\n", #T, name, offsetof(T, f))

