    printf("// Generated by gen/layout.c from libvpl API %d.%d, do not edit.\n", MFX_VERSION_MAJOR, MFX_VERSION_MINOR);
    printf("// Regenerate with cargo xtask layout vpl in the devshell.\n");
    printf("#![allow(dead_code, non_upper_case_globals)]\n\n");
    printf("pub const API_MAJOR: u16 = %d;\npub const API_MINOR: u16 = %d;\n\n", MFX_VERSION_MAJOR, MFX_VERSION_MINOR);

